/**
 * Phosphor icons as vector paths, so the pack ships no drawables. The path data is
 * @phosphor-icons/core 2.1.1 (MIT), drawn in its own 256-unit box and scaled by the icon.
 *
 * All six weights are here, thin to bold plus fill and duotone; only the one in use is built into
 * an [ImageVector]. The rest of the panel keeps naming Material icons; [resolve] swaps one for its
 * Phosphor twin, so a control the pack does not carry keeps its Material look.
 */
internal object PhosphorIcons {
    /** Phosphor twin of [icon] in [weight], or null when the pack has none. */
    fun resolve(icon: ImageVector, weight: PhosphorWeight): ImageVector? {
        val name = twins[icon] ?: return null
        return vector(name, weight)
    }

    /**
     * The Menu button's twin. Its own drawings are the toggle sources (ic_menu_bars,
     * ic_menu_toggles), so it never goes through [resolve] and is looked up by hand.
     */
    fun menu(weight: PhosphorWeight): ImageVector = vector("sliders-horizontal", weight)

    /** Material icon to Phosphor name. Every icon the panel draws is listed here. */
    private val twins = IdentityHashMap<ImageVector, String>().apply {
        put(Icons.Filled.Accessibility, "wheelchair")
        put(Icons.Filled.Apps, "squares-four")
        put(Icons.Filled.CameraAlt, "camera")
        put(Icons.Filled.ClosedCaption, "closed-captioning")
        put(Icons.Filled.DarkMode, "moon")
        put(Icons.Filled.FastForward, "fast-forward")
        put(Icons.Filled.FastRewind, "rewind")
        put(Icons.Filled.GraphicEq, "waveform")
        put(Icons.Filled.Headphones, "headphones")
        put(Icons.Filled.Home, "house")
        put(Icons.Filled.Coffee, "coffee")
        put(Icons.Filled.Input, "monitor-arrow-up")
        put(Icons.Filled.Layers, "stack")
        put(Icons.Filled.Lock, "lock-simple")
        put(Icons.Filled.Menu, "sliders-horizontal")
        put(Icons.Filled.MusicNote, "music-notes")
        put(Icons.Filled.Notifications, "bell")
        put(Icons.Filled.Pause, "pause")
        put(Icons.Filled.Person, "user")
        put(Icons.Filled.PhotoLibrary, "images")
        put(Icons.Filled.PlayArrow, "play")
        put(Icons.Filled.PowerSettingsNew, "power")
        put(Icons.Filled.Search, "magnifying-glass")
        put(Icons.Filled.Settings, "gear-six")
        put(Icons.Filled.Speaker, "speaker-high")
        put(Icons.Filled.SportsEsports, "game-controller")
        put(Icons.Filled.Timer, "timer")
        put(Icons.Filled.Tv, "television")
        put(Icons.Filled.VolumeOff, "speaker-slash")
        put(Icons.Filled.VolumeUp, "speaker-high")
        put(Icons.Filled.Wifi, "wifi-high")
        put(Icons.Filled.WifiOff, "wifi-slash")
        put(Icons.Filled.Bluetooth, "bluetooth")
    }

    /** Built icons, keyed by name and weight, so switching weights stays cheap. */
    private val cache = HashMap<String, ImageVector>()

    /** One path of an icon. Duotone draws its shape at 0.2 and the outline on top of it. */
    private class Shape(val d: String, val alpha: Float = 1f)

    private fun vector(name: String, weight: PhosphorWeight): ImageVector =
        cache.getOrPut(name + '/' + weight) {
            val paths = pathsFor(weight)[name] ?: regular.getValue(name)
            val builder = ImageVector.Builder(
                name = "Phosphor." + name + '.' + weight,
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 256f,
                viewportHeight = 256f,
            )
            paths.forEach { shape ->
                builder.addPath(addPathNodes(shape.d), fill = SolidColor(Color.Black), fillAlpha = shape.alpha)
            }
            builder.build()
        }

    private fun pathsFor(weight: PhosphorWeight): Map<String, List<Shape>> = when (weight) {
        PhosphorWeight.THIN -> thin
        PhosphorWeight.LIGHT -> light
        PhosphorWeight.REGULAR -> regular
        PhosphorWeight.BOLD -> bold
        PhosphorWeight.FILL -> fill
        PhosphorWeight.DUOTONE -> duotone
    }

